/**
 * A contract with no parameters.
 */
@contract def bare() = sigmaProp(HEIGHT > 1000)

/**
 * One defaulted, one not.
 * @param base base value
 * @param delta the increment
 */
@contract def mixed(base: Long, delta: Long = 5L) = sigmaProp(base + delta > 0L)

/**
 * Height-locked contract.
 * @param threshold the minimum height
 */
@contract def heightLock(threshold: Int) = sigmaProp(HEIGHT > threshold)

/**
 * Height-locked contract with a default.
 * @param threshold the minimum height
 */
@contract def heightLock(threshold: Int = 1000) = sigmaProp(HEIGHT > threshold)

/**
 * A returns tag carrying text — a reference reject.
 * @returns a sigma proposition
 */
@contract def retText(threshold: Int) = sigmaProp(HEIGHT > threshold)

/**
 * Range check on HEIGHT.
 * @param lo lower bound
 * @param hi upper bound
 */
@contract def rangeCheck(lo: Int, hi: Int) = sigmaProp(HEIGHT > lo && HEIGHT < hi)

/**
 * Combines a parameter flag with a height check.
 * @param enabled whether the lock is active
 * @param threshold the minimum height
 */
@contract def flagLock(enabled: Boolean, threshold: Int) = sigmaProp(enabled && HEIGHT > threshold)

/**
 * Range check with default bounds.
 * @param lo lower bound
 * @param hi upper bound
 */
@contract def rangeCheck(lo: Int = 100, hi: Int = 1000) = sigmaProp(HEIGHT > lo && HEIGHT < hi)

/**
 * String default containing a comma.
 * @param s a label
 */
@contract def strComma(s: String = "a,b") = sigmaProp(HEIGHT > 1000)

/**
 * String default containing a close paren.
 */
@contract def strParen(s: String = ")") = sigmaProp(HEIGHT > 1000)

/**
 * String default containing an escaped quote.
 */
@contract def strQuote(s: String = "\"") = sigmaProp(HEIGHT > 1000)

/**
 * Mixed params with a string default carrying a comma and paren.
 */
@contract def strMulti(a: Int = 1, s: String = "x,y)", b: Int = 2) = sigmaProp(HEIGHT > a && HEIGHT > b)

/**
 * Two parameters share a name — Scala rejects (uniqueness require).
 */
@contract def dupNames(a: Int, a: Long) = sigmaProp(HEIGHT > a)

/**
 * Five SigmaProp params whose HashTrieMap iteration order (2.12) differs from
 * both declaration and alphabetical order — the recon's p5 discriminator.
 */
@contract def gate5h(zeta: SigmaProp, alpha: SigmaProp, mike: SigmaProp, bravo: SigmaProp, oscar: SigmaProp) = zeta && alpha && mike && bravo && oscar

/**
 * Six SigmaProp params — HashTrieMap order (2.12) differs from declaration and
 * alphabetical order.
 */
@contract def gate6h(epsilon: SigmaProp, iota: SigmaProp, nu: SigmaProp, rho: SigmaProp, tau: SigmaProp, phi: SigmaProp) = epsilon && iota && nu && rho && tau && phi

/**
 * Eight SigmaProp params — the recon's p8 discriminator; includes the
 * zeta/bravo and delta/beta root-bucket collisions.
 */
@contract def gate8h(sigma: SigmaProp, delta: SigmaProp, kappa: SigmaProp, omega: SigmaProp, theta: SigmaProp, gamma: SigmaProp, lambda: SigmaProp, beta: SigmaProp) = sigma && delta && kappa && omega && theta && gamma && lambda && beta

/**
 * One param read in two sibling `&&` right arms: Scala builds the placeholder
 * at the root, so both arms share it and it becomes one ValDef.
 */
@contract def reuseAnd(a: Int) = sigmaProp(HEIGHT > 0 && a > 1 && a < 9)

/**
 * Four params; only `d` is read twice, in two sibling `&&` right arms.
 */
@contract def reuseAnd4(a: Int, b: Int, c: Int, d: Int) = sigmaProp(a > 0 && b > 1 && c + d > 0 && d > 1)

/**
 * One param read in both branches of an `if` (each branch is its own thunk).
 */
@contract def reuseIf(a: Int) = sigmaProp(if (HEIGHT > 5) a > 1 else a < 9)

/**
 * A tuple param projected in two sibling `&&` right arms: the shared
 * placeholder is the projections' receiver.
 */
@contract def reusePair(x: Int, pair: (Int, Long)) = sigmaProp(x > 0 && pair._1 > 0 && pair._2 > 0L)

/**
 * Six params, three of them read twice, one only across `&&` right arms
 * (`echo`); exercises the shared-placeholder ValDefs under Scala 2.12
 * HashTrieMap placeholder order.
 */
@contract def reuse6(alpha: Int, bravo: Int, charlie: Int, delta: Int, echo: Int, foxtrot: Int) = sigmaProp(foxtrot > alpha && alpha > foxtrot - 1 && bravo + charlie + delta + echo > 0 && echo > 1)

/**
 * Six params of richer types; the tuple param is projected in two sibling
 * `&&` right arms.
 */
@contract def reuseTypes6(ge: GroupElement, bi: BigInt, pair: (Int, Long), nested: Coll[Coll[Byte]], b: Byte, sh: Short) = proveDlog(ge) && sigmaProp(bi > 0.toBigInt && pair._1 > 0 && pair._2 > 0L && nested.size > 0 && b > 0.toByte && sh > 0.toShort)
